// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(uint256 unused) public {

        bool ok;
        try c.version() returns (string memory v) {
            ok = (keccak256(bytes(v)) == keccak256(bytes("1.0.0")));
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
